import Foundation

// MARK: - Response

struct BookingResponse: Codable {
    let status: Bool
    let status_code: Int
    let data: BookingData
}

struct BookingListRequest: Codable {
    let email: String
    let site_id: String
    let type: String
}

struct BookingData: Codable {
    let count: Int
    let bookings: [Booking]

    enum CodingKeys: String, CodingKey {
        case count
        case bookings
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        count = try container.decodeIfPresent(Int.self, forKey: .count) ?? 0
        bookings = try container.decodeIfPresent([Booking].self, forKey: .bookings) ?? []
    }
}

// MARK: - Booking
struct Booking: Codable, Identifiable {
    var id: String { orderNo }
    let orderNo: String
    let bookingRef: String
    let status: TransactionStatus
    let productTitle: String
    var travellerSummary: String? = nil
    let productCode: String
    let travelDate: Date
    let currency: String
    let createdDate: Date
    let travellers: TransactionTravellerInfo
    let price: TransactionPriceDetails
    let thumbnail: String
    let time: String
    let bookingDate: Date

    enum CodingKeys: String, CodingKey {
        case orderNo = "order_no"
        case bookingRef = "booking_ref"
        case status
        case productTitle = "product_title"
        case productCode = "product_code"
        case travelDate = "travel_date"
        case currency
        case createdDate = "created_date"
        case travellers
        case price
        case thumbnail
        case time
    }

    // MARK: - Decoding
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        orderNo = try container.decode(String.self, forKey: .orderNo)
        bookingRef = try container.decode(String.self, forKey: .bookingRef)
        productTitle = try container.decode(String.self, forKey: .productTitle)
        productCode = try container.decode(String.self, forKey: .productCode)
        currency = try container.decode(String.self, forKey: .currency)
        thumbnail = try container.decode(String.self, forKey: .thumbnail)
        time = try container.decode(String.self, forKey: .time)
        let statusString = try container.decode(String.self, forKey: .status)
        status = TransactionStatus(rawValue: statusString.uppercased()) ?? .pending
        let travelDateString = try container.decode(String.self, forKey: .travelDate)
        let createdDateString = try container.decode(String.self, forKey: .createdDate)

        // Parse travel date (simple date format like "2025-09-12")
        let travelDateFormatter = DateFormatter()
        travelDateFormatter.dateFormat = "yyyy-MM-dd"
        travelDateFormatter.timeZone = TimeZone.current
        travelDate = travelDateFormatter.date(from: travelDateString) ?? Date()

        // Parse created date (simple date format "2025-10-17")
        createdDate = travelDateFormatter.date(from: createdDateString) ?? Date()
        bookingDate = createdDate
        travellers = try container.decode(TransactionTravellerInfo.self, forKey: .travellers)
//        travellerSummary = Booking.formatTravellerSummary(travellers)

        price = try container.decode(TransactionPriceDetails.self, forKey: .price)
    }

    // MARK: - Encoding
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(orderNo, forKey: .orderNo)
        try container.encode(bookingRef, forKey: .bookingRef)
        try container.encode(status.rawValue, forKey: .status)
        try container.encode(productTitle, forKey: .productTitle)
        try container.encode(productCode, forKey: .productCode)
        try container.encode(currency, forKey: .currency)

        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]

        try container.encode(formatter.string(from: travelDate), forKey: .travelDate)
        try container.encode(formatter.string(from: createdDate), forKey: .createdDate)

        // Travellers
        try container.encode(travellers, forKey: .travellers)

        // Price
        try container.encode(price, forKey: .price)
    }
}

// MARK: - Transaction Traveller Info
//struct TransactionTravellerInfo: Codable {
//    let adults: Int
//    let children: Int
//    let total: Int
//}
struct TransactionTravellerInfo: Codable {
    let adults: Int
    let children: Int
    let total: Int
    let infants: Int
    let families: Int
    let People: Int

    enum CodingKeys: String, CodingKey {
        case adults, children, total , infants, families, People
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        adults = try container.decodeIfPresent(Int.self, forKey: .adults) ?? 0
        children = try container.decodeIfPresent(Int.self, forKey: .children) ?? 0
        infants = try container.decodeIfPresent(Int.self, forKey: .infants) ?? 0
        families = try container.decodeIfPresent(Int.self, forKey: .families) ?? 0
        People = try container.decodeIfPresent(Int.self, forKey: .People) ?? 0
        total = try container.decodeIfPresent(Int.self, forKey: .total) ?? (adults + children)
    }

    init(adults: Int, children: Int,infants: Int, families: Int, People: Int) {
        self.adults = adults
        self.children = children
        self.infants = infants
        self.families = families
        self.People = People
        self.total = adults + children
    }
}


// MARK: - Transaction Price Details
struct TransactionPriceDetails: Codable {
    let baseRate: Double
    let taxes: Double
    let totalAmount: Double
    let strikeout: TransactionStrikeoutPrice?
    let currency: String
    let roeBase: Double?
    let priceType: String
    let pricePerAge: [TransactionPricePerAge]

    enum CodingKeys: String, CodingKey {
        case baseRate = "base_rate"
        case taxes
        case totalAmount = "total_amount"
        case strikeout
        case currency
        case roeBase = "roe_base"
        case priceType = "price_type"
        case pricePerAge = "price_per_age"
    }
}

// MARK: - Transaction Price Per Age
struct TransactionPricePerAge: Codable {
    let bandId: String
    let perPriceTraveller: Double
    let count: Int
    let bandTotal: Double

    enum CodingKeys: String, CodingKey {
        case bandId = "band_id"
        case perPriceTraveller = "per_price_traveller"
        case count
        case bandTotal = "band_total"
    }
}

// MARK: - Transaction Strikeout Price
struct TransactionStrikeoutPrice: Codable {
    let baseRate: Double
    let taxes: Double
    let totalAmount: Double
    let savingPercentage: Double
    let savingAmount: Double

    enum CodingKeys: String, CodingKey {
        case baseRate = "base_rate"
        case taxes
        case totalAmount = "total_amount"
        case savingPercentage = "saving_percentage"
        case savingAmount = "saving_amount"
    }
}

// MARK: - Status
enum TransactionStatus: String, Codable {
    case confirmed = "CONFIRMED"
    case pending = "PENDING"
    case cancelled = "CANCELLED"
    case completed = "COMPLETED"
    case failed = "FAILED"
    case refunded = "REFUNDED"
}

// MARK: - Tabs
enum TransactionTab: String, CaseIterable, Identifiable {
    var id: String { rawValue }
    case Upcoming
    case Completed
    case Cancelled
}

// MARK: - Helpers
extension Booking {
//    var travellerText: String {
//        var parts: [String] = []
//        if travellers.adults > 0 { parts.append("\(travellers.adults) Adult\(travellers.adults > 1 ? "s" : "")") }
//        if travellers.children > 0 { parts.append("\(travellers.children) Child\(travellers.children > 1 ? "ren" : "")") }
//        return parts.joined(separator: ", ")
//    }

    var timeText: String {
        let formatter = DateFormatter()
        formatter.dateFormat = "HH:mm"
        formatter.timeZone = TimeZone.current
        return formatter.string(from: createdDate)
    }

    // Convenience properties for accessing traveller data
    var adults: Int { travellers.adults }
    var children: Int { travellers.children }
    var families: Int { travellers.families }
    var totalTravellers: Int { travellers.total }

    // Savings amount from price data
    var savings: Decimal? {
        guard let strikeout = price.strikeout else { return nil }
        return Decimal(strikeout.savingAmount)
    }

    // Savings percentage from price data
    var savingsPercentage: Decimal? {
        guard let strikeout = price.strikeout else { return nil }
        return Decimal(strikeout.savingPercentage).rounded()
    }
}
extension Booking {
    var travellerText: String {
        var parts: [String] = []

        // Adults from travellers.adults
        if travellers.adults > 0 {
            parts.append("\(travellers.adults) Adult\(travellers.adults > 1 ? "s" : "")")
        }

        // Children: Prefer travellers.children, but fallback to price.pricePerAge
        var childrenCount = travellers.children
        if childrenCount == 0 {
            childrenCount = price.pricePerAge.first(where: { $0.bandId.uppercased() == "CHILD" })?.count ?? 0
        }
        if childrenCount > 0 {
            parts.append("\(childrenCount) Child\(childrenCount > 1 ? "ren" : "")")
        }

        if travellers.families > 0 {
            parts.append("\(travellers.families) \(travellers.families > 1 ? "Families" : "Family")")
        }

        // Infants
        if travellers.infants > 0 {
            parts.append("\(travellers.infants) Infant\(travellers.infants > 1 ? "s" : "")")
        }

        return parts.isEmpty ? "No Participants" : parts.joined(separator: ", ")
    }
}

import SwiftUI

struct TransactionRow: View {
    let item: Booking
    var participantsSummary: String = ""

    init(item: Booking) {
        self.item = item
        let pricePerAge = item.price.pricePerAge

        let parts: [String] = pricePerAge.compactMap { item in
            guard item.count > 0 else { return nil }

            let label: String

            switch item.bandId.uppercased() {
            case "ADULT":
                label = item.count == 1 ? "Adult" : "Adults"
            case "CHILD":
                label = item.count == 1 ? "Child" : "Children"
            case "INFANT":
                label = item.count == 1 ? "Infant" : "Infants"
            case "FAMILY":
                label = item.count == 1 ? "Family" : "Families"
            case "PERSON":
                label = item.count == 1 ? "Person" : "People"
            case "CUSTOM":
                label = "Custom"
            default:
                label = item.count == 1 ? item.bandId.capitalized : "\(item.bandId.capitalized)s"
            }

            return "\(item.count) \(label)"
        }

        participantsSummary = parts.isEmpty ? "No participants" : parts.joined(separator: ", ")
    }

    // MARK: - Savings Text Function
    private func createSavingsText(savingAmount: Double, currency: String) -> AttributedString {
        var text = AttributedString(Constants.TransactionRowConstants.youAreSaving)
        text.foregroundColor = .gray
        var value = AttributedString("\(savingAmount.commaSeparated()) \(currency)")
        value.foregroundColor = Color(hex: Constants.HexColors.greenShade)
        value.font = .system(size: 14, weight: .bold)
        text.append(value)
        return text
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {

            // Top: image + title + booking details
            HStack(alignment: .top, spacing: 12) {
                //item.
                if let thumbnailUrl = URL(string: item.thumbnail), !item.thumbnail.isEmpty {
                    // Display image from API using AsyncImage (iOS 15+)
                    AsyncImage(url: thumbnailUrl) { phase in
                        switch phase {
                        case .empty:
                            ProgressView()
                                .frame(width: 76, height: 76)
                        case .success(let image):
                            image
                                .resizable()
                                .scaledToFill()
                                .frame(width: 76, height: 76)
                                .clipShape(RoundedRectangle(cornerRadius: 10))
                        case .failure:
                            if let placeholder = ImageLoader.bundleImage(named: Constants.TransactionRowConstants.placeHolderImage) {
                                placeholder
                                    .resizable()
                                    .scaledToFill()
                                    .frame(width: 76, height: 76)
                                    .clipped()
                                    .clipShape(RoundedCorner(radius: 12, corners: [.topLeft, .bottomLeft]))
                            }
                        @unknown default:
                            if let placeholder = ImageLoader.bundleImage(named: Constants.TransactionRowConstants.placeHolderImage) {
                                placeholder
                                    .resizable()
                                    .scaledToFill()
                                    .frame(width: 76, height: 76)
                                    .clipped()
                                    .clipShape(RoundedCorner(radius: 12, corners: [.topLeft, .bottomLeft]))
                            }
                        }
                    }
                } else if let uiImage = UIImage(named: Constants.TransactionRowConstants.placeHolderImage) {
                    Image(uiImage: uiImage)
                        .resizable()
                        .scaledToFill()
                        .frame(width: 76, height: 76)
                        .clipShape(RoundedRectangle(cornerRadius: 10))
                } else {
                    // Fallback if image not found
                    RoundedRectangle(cornerRadius: 10)
                        .fill(Color.gray.opacity(0.2))
                        .frame(width: 76, height: 76)
                        .overlay(
                            Image(systemName: Constants.TransactionRowConstants.systemPhoto)
                                .font(.system(size: 24))
                                .foregroundColor(.gray)
                        )
                }

                VStack(alignment: .leading, spacing: 6) {
                    Text(item.productTitle)
                        .font(.custom("OpenSans-SemiBold", size: 14))
                        .foregroundColor(.black)
                        .lineLimit(2)
                        .multilineTextAlignment(.leading)

                    HStack(spacing: 4) {
                        Text(Constants.TransactionRowConstants.bookingId)
                            .foregroundColor(.black)
                            .font(.custom("OpenSans-SemiBold", size: 12))
                        Text(item.orderNo)
                            .foregroundColor(.gray)
                            .font(.custom("OpenSans-SemiBold", size: 12))

                        Spacer()
                    }
                    .font(.subheadline)

                    HStack(spacing: 4) {
                        Text(Constants.TransactionRowConstants.bookingDate)
                            .font(.custom("OpenSans-SemiBold", size: 12))
                            .foregroundColor(.black)
                        Text(DateFormatter.shortDate.string(from: item.bookingDate))
                            .font(.custom("OpenSans-SemiBold", size: 12))
                            .foregroundColor(.gray)
                    }
                    .font(.subheadline)
                }

            }

            Divider()

            VStack(alignment: .leading, spacing: 8) {
                HStack {
                    if let calendarIcon = ImageLoader.bundleImage(named: Constants.Icons.calendargray) {
                        calendarIcon
                            .resizable()
                            .frame(width: 20, height: 20)
                            .foregroundStyle(.secondary)
                    }
                    Text(DateFormatter.shortDate.string(from: item.travelDate))
                        .font(.custom("OpenSans-SemiBold", size: 12))
                    Spacer()

                    if let icon = ImageLoader.bundleImage(named: Constants.Icons.usergray) {
                        HStack(spacing: 6) {
                            icon
                                .resizable()
                                .frame(width: 20, height: 20)
                                .foregroundStyle(.secondary)
                            Text(participantsSummary)
                                .font(.custom("OpenSans-SemiBold", size: 12))
                                .foregroundColor(.secondary)
                        }
                    } else {
                        Label(participantsSummary, image: Constants.Icons.usergray)
                            .font(.custom("OpenSans-SemiBold", size: 12))
                    }
                    Spacer()
                }

                .font(.subheadline)
                .foregroundColor(.secondary)

                if !item.time.isEmpty && item.time != "00:00" {
                    HStack {
                        if let clockIcon = ImageLoader.bundleImage(named: Constants.Icons.clock) {
                            clockIcon
                                .resizable()
                                .frame(width: 20, height: 20)
                                .foregroundStyle(.secondary)
                        }
                        Text(item.time)
                            .font(.custom("OpenSans-SemiBold", size: 12))
                            .foregroundColor(.secondary)
                    }
                }

                if let strikeout = item.price.strikeout {
                    Label {
                        Text(createSavingsText(
                            savingAmount: strikeout.savingAmount,
                            currency: item.price.currency
                        ))
                        .font(.custom("OpenSans-SemiBold", size: 12))
                    } icon: {
                        if let savingIcon = ImageLoader.bundleImage(named: Constants.Icons.savingGray) {
                            savingIcon
                                .resizable()
                                .frame(width: 20, height: 20)
                                .colorMultiply(.gray)
                        }
                    }
                }
            }

            // Bottom: Status
            HStack {
                Spacer()
                Text(Constants.TransactionRowConstants.status)
                    .font(.custom("OpenSans-SemiBold", size: 12))
                    .foregroundColor(.gray)

                Text(getStatusValue())
                    .font(.custom("OpenSans-SemiBold", size: 12))
                    .padding(.vertical, 4)
                    .padding(.horizontal, 10)
                    .background(item.status.color)
                    .foregroundColor(.white)
                    .cornerRadius(6)
            }
        }
        .padding(10)
        .background(
            RoundedRectangle(cornerRadius: 12)
                .fill(Color.white)
                .overlay(
                    RoundedRectangle(cornerRadius: 12)
                        .stroke(Color(.systemGray4), lineWidth: 1)
                )
        )
    }

    func getStatusValue() -> String {
        switch item.status {
        case .confirmed,.pending, .completed, .failed:
            return item.status.rawValue.capitalized

        case .cancelled, .refunded:
            return "Cancelled"
        }
    }
}

